#!/bin/sh
# caret — command-line launcher for the Caret editor (like VS Code's `code`).
# Generated by Caret __CARET_VERSION__. Do not edit: Caret rewrites this file when the app moves or updates.
# Install/uninstall from the command palette: "Shell Command: Install 'caret' command in PATH".
BUNDLE_ID="__CARET_BUNDLE_ID__"
APP_PATH="__CARET_APP_PATH__"
VERSION="__CARET_VERSION__"

usage() {
  cat <<USAGE
Usage: caret [options] [paths...]

Open folders and files in Caret.

  caret                  launch or focus Caret
  caret .                open the current folder as the workspace
  caret src/app.ts       open a file (its folder becomes the workspace if none is open)
  caret -g app.ts:12:4   open a file at line 12, column 4 (a bare app.ts:12:4 works too)
  caret serve            run Caret and serve its UI to browsers on your LAN or over Tailscale

Options:
  -g, --goto <file:line[:col]>   open a file at a position
  -n, --new-window               accepted for compatibility (Caret is single-window)
  -r, --reuse-window             accepted for compatibility
  -w, --wait                     accepted for compatibility (does not wait)
  -v, --version                  print the version
  -h, --help                     show this help

Serve (caret serve [options] [paths...]; prints the URL and a pairing code, Ctrl-C stops):
  --host <addr>                  bind address: 127.0.0.1 (default, this Mac only) or 0.0.0.0 (LAN / Tailscale)
  --port <n>                     port (default 17430)
  --no-window                    hide the desktop window (the app keeps running; the window still exists)
  --print-url                    print only the URL(s), no pairing code
USAGE
}

# `caret serve …` runs the app binary directly so its stdout (URL + pairing code) lands in this terminal.
serve_app() {
  bin="$APP_PATH/Contents/MacOS/caret"
  if [ -f "$APP_PATH" ] && [ -x "$APP_PATH" ]; then bin=$APP_PATH; fi
  for a in "$@"; do case "$a" in -h|--help) usage; exit 0 ;; esac; done
  if [ -n "$CARET_CLI_DRY_RUN" ]; then
    printf 'exec %s serve' "$bin"; for x in "$@"; do printf ' %s' "$x"; done; printf '\n'; exit 0
  fi
  if [ ! -x "$bin" ]; then echo "caret: cannot find the Caret binary at $bin" >&2; exit 1; fi
  exec "$bin" serve "$@"
}
if [ "$1" = "serve" ]; then shift; serve_app "$@"; fi

is_num() { case "$1" in ''|*[!0-9]*) return 1 ;; esac; return 0; }

# Absolute, symlink-resolved path (so /tmp → /private/tmp matches what Caret shows). Missing files keep their name.
abspath() {
  p=$1
  case "$p" in
    "~") p=$HOME ;;
    "~/"*) p=$HOME/${p#"~/"} ;;
  esac
  case "$p" in /*) ;; *) p=$PWD/$p ;; esac
  if [ -d "$p" ]; then
    (cd -P -- "$p" 2>/dev/null && pwd) || printf '%s' "$p"
  else
    d=$(dirname -- "$p"); b=$(basename -- "$p")
    if [ -d "$d" ]; then
      rd=$(cd -P -- "$d" 2>/dev/null && pwd)
      case "$rd" in /) printf '/%s' "$b" ;; *) printf '%s/%s' "$rd" "$b" ;; esac
    else
      printf '%s' "$p"
    fi
  fi
}

# Percent-encode everything except unreserved characters and '/'.
urlencode() {
  printf '%s' "$1" | od -An -tx1 -v | tr ' ' '\n' | while read -r hex; do
    [ -z "$hex" ] && continue
    case "$hex" in
      2f|2d|2e|5f|7e|3[0-9]|4[1-9a-f]|5[0-9a]|6[1-9a-f]|7[0-9a]) printf "\\$(printf '%o' "0x$hex")" ;;
      *) printf '%%%s' "$hex" ;;
    esac
  done
}

# running_app: bundle path of the Caret that is running right now, or nothing.
# Several copies of Caret.app can share one bundle id (a hand-copied /Applications/Caret.app next to the Homebrew
# cask in ~/Applications, a build under target/). `open -b` then lets LaunchServices pick a copy, and that copy may
# not be the running one: a cold start and a second window instead of an open event to the window you work in.
# CARET_CLI_RUNNING_APP (set, possibly empty) pins the answer so dry runs and tests never ask LaunchServices.
running_app() {
  if [ -n "${CARET_CLI_RUNNING_APP+set}" ]; then printf '%s' "$CARET_CLI_RUNNING_APP"; return 0; fi
  p=""
  if command -v lsappinfo >/dev/null 2>&1; then
    p=$(lsappinfo info -only bundlepath "$BUNDLE_ID" 2>/dev/null | sed -n 's/^"LSBundlePath"="\(.*\)"$/\1/p' | head -n 1)
  fi
  if [ -z "$p" ] && command -v pgrep >/dev/null 2>&1; then
    p=$(pgrep -fl "Caret.app/Contents/MacOS/caret" 2>/dev/null | sed -n 's|^[0-9][0-9]* \(.*\.app\)/Contents/MacOS/caret.*$|\1|p' | head -n 1)
  fi
  if [ -n "$p" ] && [ -d "$p" ]; then printf '%s' "$p"; fi
  return 0
}

# open_with_app <documents or URLs...>: hands them to Caret through LaunchServices.
# Target order: the running copy (`open -a <bundle>`, so the event reaches the window you already have), then the
# copy this script was rendered for while it is still an app bundle, then the bundle id (first run after a fresh
# build; dev builds, whose APP_PATH is a bare binary). The dry run prints exactly the command that would run.
open_with_app() {
  running=$(running_app)
  if [ -n "$running" ]; then how=-a; who=$running
  elif [ -d "$APP_PATH" ]; then how=-a; who=$APP_PATH
  else how=-b; who=$BUNDLE_ID; fi
  if [ -n "$CARET_CLI_DRY_RUN" ]; then
    printf 'open %s %s' "$how" "$who"; for x in "$@"; do printf ' %s' "$x"; done; printf '\n'; return 0
  fi
  if command -v open >/dev/null 2>&1; then
    open "$how" "$who" "$@" 2>/dev/null && return 0
    # The preferred copy did not take it (moved, half-installed): try the other selectors before giving up.
    if [ "$how" != -b ]; then open -b "$BUNDLE_ID" "$@" 2>/dev/null && return 0; fi
    if [ "$who" != "$APP_PATH" ] && [ -d "$APP_PATH" ]; then open -a "$APP_PATH" "$@" 2>/dev/null && return 0; fi
    echo "caret: could not launch Caret (bundle $BUNDLE_ID, app $APP_PATH). Launch Caret once from Finder and retry." >&2
    return 1
  fi
  # Not macOS: start the binary directly with the paths as arguments.
  bin=$APP_PATH; [ -x "$APP_PATH/Contents/MacOS/caret" ] && bin="$APP_PATH/Contents/MacOS/caret"
  "$bin" "$@" >/dev/null 2>&1 &
  return 0
}

# Split file:line[:col] from the right. Sets G_FILE, G_LINE, G_COL.
split_goto() {
  spec=$1; G_FILE=$spec; G_LINE=""; G_COL=""
  tail=${spec##*:}; head=${spec%:*}
  if [ "$head" != "$spec" ] && is_num "$tail"; then
    tail2=${head##*:}; head2=${head%:*}
    if [ "$head2" != "$head" ] && is_num "$tail2"; then G_FILE=$head2; G_LINE=$tail2; G_COL=$tail
    else G_FILE=$head; G_LINE=$tail; fi
  fi
}

PATHS=""; GOTOS=""; STATUS=0; NL='
'
add_path() {
  if [ -e "$1" ]; then PATHS="$PATHS$(abspath "$1")$NL"; return; fi
  split_goto "$1"
  if [ -n "$G_LINE" ] && [ -e "$G_FILE" ]; then add_goto "$1"; return; fi
  echo "caret: no such file or directory: $1" >&2; STATUS=1
}
add_goto() {
  split_goto "$1"
  if [ ! -e "$G_FILE" ]; then echo "caret: no such file or directory: $G_FILE" >&2; STATUS=1; return; fi
  if [ -d "$G_FILE" ]; then PATHS="$PATHS$(abspath "$G_FILE")$NL"; return; fi
  url="caret://open?path=$(urlencode "$(abspath "$G_FILE")")"
  [ -n "$G_LINE" ] && url="$url&line=$G_LINE"
  [ -n "$G_COL" ] && url="$url&col=$G_COL"
  GOTOS="$GOTOS$url$NL"
}

while [ $# -gt 0 ]; do
  case "$1" in
    -h|--help) usage; exit 0 ;;
    -v|--version) echo "caret $VERSION"; exit 0 ;;
    -g|--goto) shift; [ $# -gt 0 ] || { echo "caret: --goto needs a file:line[:col] argument" >&2; exit 2; }; add_goto "$1" ;;
    --goto=*) add_goto "${1#--goto=}" ;;
    -n|--new-window|-r|--reuse-window|-w|--wait|-a|--add|--) ;;
    -*) echo "caret: unknown option '$1'" >&2; usage >&2; exit 2 ;;
    *) add_path "$1" ;;
  esac
  shift
done

if [ -z "$PATHS" ] && [ -z "$GOTOS" ]; then
  [ $STATUS -eq 0 ] && open_with_app
  exit $STATUS
fi
if [ -n "$PATHS" ]; then
  # shellcheck disable=SC2086
  old_ifs=$IFS; IFS=$NL; set -f; set -- $PATHS; set +f; IFS=$old_ifs
  open_with_app "$@" || STATUS=1
fi
if [ -n "$GOTOS" ]; then
  old_ifs=$IFS; IFS=$NL; set -f; set -- $GOTOS; set +f; IFS=$old_ifs
  for u in "$@"; do open_with_app "$u" || STATUS=1; done
fi
exit $STATUS
